def clamp(value: float, low: float, high: float) -> float:
    """Return ``value`` limited to ``[low, high]``.

    Raises:
        ValueError: if ``low`` is greater than ``high``.
    """
    if low > high:
        raise ValueError(f"low ({low}) must not exceed high ({high})")
    if value < low:
        return low
    if value > high:
        return high
    return value
