{"files": [{"path": "tests/test_clamp.py", "content": "import pytest
from hypothesis import given
from hypothesis import strategies as st

from clamp import clamp


@given(st.integers(), st.integers(), st.integers())
def test_result_always_lies_within_the_bounds(value, a, b):
    low, high = min(a, b), max(a, b)
    assert low <= clamp(value, low, high) <= high


def test_value_inside_the_range_is_unchanged():
    assert clamp(5, 0, 10) == 5


def test_value_below_the_range_becomes_low():
    assert clamp(-3, 0, 10) == 0


def test_value_above_the_range_becomes_high():
    assert clamp(42, 0, 10) == 10


def test_bounds_are_inclusive():
    assert clamp(0, 0, 10) == 0
    assert clamp(10, 0, 10) == 10


def test_equal_bounds_return_that_bound():
    assert clamp(7, 3, 3) == 3
    assert clamp(-7, 3, 3) == 3


def test_floats_are_supported():
    assert clamp(0.5, 0.0, 1.0) == 0.5
    assert clamp(1.5, 0.0, 1.0) == 1.0


def test_inverted_range_raises():
    with pytest.raises(ValueError):
        clamp(1, 5, 0)


def test_just_outside_each_bound():
    assert clamp(-1, 0, 10) == 0
    assert clamp(11, 0, 10) == 10
